ool => $variant->optionValues->contains('id', $value->id)))<button wire:key="option-{{ $option->id }}-{{ $value->id }}" wire:click="selectOption({{ $option->id }}, {{ $value->id }})" type="button" aria-pressed="{{ ($selectedOptions[$option->id] ?? null) === $value->id ? 'true' : 'false' }}" @disabled(!$available) class="rounded-lg border px-4 py-2 text-sm hover:border-blue-600 disabled:cursor-not-allowed disabled:opacity-40 {{ ($selectedOptions[$option->id] ?? null) === $value->id ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-zinc-300 dark:border-zinc-700' }}">{{ $value->value }}</button>@endforeach</div></fieldset>@endforeach@if ($soldOut)<p class="mt-8 font-semibold text-red-600" aria-live="polite">Sold out</p>@elseif ($selectedVariant?->inventory?->policy?->value === 'continue' && $selectedVariant->availableQuantity() <= 0)<p class="mt-8 font-semibold text-amber-600" aria-live="polite">Available on backorder</p>@endif<div class="mt-8 flex gap-3"><label class="sr-only" for="quantity">Quantity</label><input id="quantity" type="number" min="1" wire:model="quantity" class="w-24 rounded-full border border-zinc-300 px-4 py-3 text-center dark:border-zinc-700 dark:bg-zinc-900"><button wire:click="addToCart" wire:loading.attr="disabled" @disabled($soldOut) class="flex-1 rounded-full bg-blue-600 px-6 py-3 font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"><span wire:loading.remove wire:target="addToCart">{{ $soldOut ? 'Sold out' : 'Add to cart' }}</span><span wire:loading wire:target="addToCart">Adding…</span></button></div>@error('quantity')<p class="mt-4 text-sm font-semibold text-red-600">{{ $message }}</p>@enderror@if ($message)<p class="mt-4 text-sm font-semibold text-green-600" role="status">{{ $message }}</p>@endif</div></div>
